def _pipepager(
    cmd_parts: list[str], color: bool | None = None
) -> t.Iterator[tuple[t.BinaryIO, bool]]:
    """Page through text by feeding it to another program.

    The pager is invoked with :class:`subprocess.Popen` in text mode and an
    ``errors="replace"`` handler, so text that cannot be represented in the
    pager's encoding is written as a replacement character instead of raising.
    """

stdin = t.cast(t.BinaryIO, c.stdin)
    try:
        yield stdin, color

